command:
$ErrorActionPreference = "Stop"
Write-Host "===== BOOKMARK PRE-MAIN VALIDATION RETRY ====="
git fetch origin main work/bookmarks-winui --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }
Write-Host "LOCAL_BRANCH=$(git branch --show-current)"
Write-Host "LOCAL_HEAD=$(git rev-parse HEAD)"
Write-Host "ORIGIN_MAIN=$(git rev-parse origin/main)"
Write-Host "ORIGIN_BOOKMARK=$(git rev-parse origin/work/bookmarks-winui)"
$status = @(git status --short)
if ($status.Count -ne 0) {
  $status | ForEach-Object { Write-Host $_ }
  throw "persistent checkout has unexpected local changes"
}
if ((git rev-parse origin/main).Trim() -ne "5228cbbfc24f56d61a84975545f1d8572e7deece") {
  throw "main moved after request snapshot"
}
if ((git branch --show-current) -ne "work/bookmarks-winui") {
  if (git show-ref --verify --quiet refs/heads/work/bookmarks-winui) {
    git checkout work/bookmarks-winui
  } else {
    git checkout -b work/bookmarks-winui --track origin/work/bookmarks-winui
  }
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout bookmark branch" }
}
git merge --ff-only origin/work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward bookmark branch" }
Write-Host "BOOKMARK_BRANCH_HEAD=$(git rev-parse HEAD)"

Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

Write-Host "NATIVE_RELEASE"
cmd /c tests\winui\m20\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M20 Release build failed" }
cmd /c "set FLY_M20_CONFIG=Release&& python -X utf8 tests\winui\m20\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M20 Release native test failed" }

Write-Host "BUILD_CHANGED_RELEASE"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "changed Release build failed" }

Write-Host "OWNED_GUI_RELEASE"
python -X utf8 tools\winui\run_checks.py gui --configuration Release
if ($LASTEXITCODE -ne 0) { throw "owned Release GUI failed" }

if (-not (Test-Path "logs\capture-bookmark-visual.py")) {
  throw "before-run capture helper missing"
}
$env:BOOKMARK_VISUAL_MODE = "after"
python -X utf8 logs\capture-bookmark-visual.py
if ($LASTEXITCODE -ne 0) { throw "after capture failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }
Write-Host "FINAL_STATUS"
git status --short
Write-Host "BOOKMARK_PREMAIN_VALIDATION_PASS"
